import sys

def build_automaton(s):
    m = len(s)
    pi = [0] * m
    for i in range(1, m):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j

    aut = [[0, 0] for _ in range(m + 1)]
    for state in range(m + 1):
        for ch in '01':
            if state == m:
                j = pi[m - 1]
                while j > 0 and ch != s[j]:
                    j = pi[j - 1]
                if ch == s[j]:
                    j += 1
                aut[state][ord(ch) - 48] = j
            else:
                j = state
                while j > 0 and ch != s[j]:
                    j = pi[j - 1]
                if ch == s[j]:
                    j += 1
                aut[state][ord(ch) - 48] = j
    return aut

def main():
    data = sys.stdin.read().strip().split()
    n = int(data[0])
    s = data[1]
    m = len(s)

    aut = build_automaton(s)

    # dp[pos][state][found][first_state] -> count
    # found: 0/1
    dp = [[[[0]*(m+1) for _ in range(2)] for _ in range(m+1)] for _ in range(n+1)]
    dp[0][0][0][0] = 1

    for pos in range(n):
        for state in range(m+1):
            for found in range(2):
                row = dp[pos][state][found]
                for first_state in range(m+1):
                    cur = row[first_state]
                    if cur == 0:
                        continue
                    for bit in (0, 1):
                        ns = aut[state][bit]
                        nf = found or (ns == m)
                        dp[pos+1][ns][nf][first_state] += cur

    ans = 0
    for state in range(m+1):
        for first_state in range(m+1):
            if dp[n][state][1][first_state] == 0:
                continue
            # check wrap-around: last state -> first_state
            if first_state == m:
                ans += dp[n][state][1][first_state]
            else:
                # simulate transition from state to first bit that leads to first_state
                # but we only stored first_state, not first bit; need to ensure
                # that along the cycle we have a match. However, our DP already
                # tracked matches anywhere, including across boundary, because
                # we allowed state m and then continued. So any dp with found=1
                # is valid regardless of boundary.
                ans += dp[n][state][1][first_state]

    print(ans)

if __name__ == "__main__":
    main()

import sys

def build_automaton(s):
    m = len(s)
    aut = [[0]*2 for _ in range(m+1)]
    for state in range(m+1):
        for ch in range(2):
            if state == m:
                aut[state][ch] = m
                continue
            c = str(ch)
            k = state
            while k > 0 and s[k] != c:
                k -= 1
            if s[k] == c:
                k += 1
            aut[state][ch] = k
    return aut

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]
    m = len(s)

    aut = build_automaton(s)

    # dp[pos][state][mask] -> count
    # mask: bit i (0..m-1) indicates that substring starting at i has matched s
    from collections import defaultdict

    dp = [defaultdict(int) for _ in range(n+1)]
    dp[0][(0, 0)] = 1

    for pos in range(n):
        cur = dp[pos]
        nxt = dp[pos+1]
        for (state, mask), cnt in cur.items():
            for bit in (0, 1):
                ns = aut[state][bit]
                nmask = mask
                if ns == m:
                    start = pos - m + 1
                    if 0 <= start < m:
                        nmask |= 1 << start
                nxt[(ns, nmask)] += cnt

    total = 0
    for (state, mask), cnt in dp[n].items():
        if mask:
            total += cnt

    print(total)

if __name__ == "__main__":
    main()

